const coiTable=coi=>({title:'Native COI edge adjustment',note:coi.scope,headings:['Field','Value'],rows:[['Status',coi.status],['Selected source',coi.source_name],['Source SHA-256',coi.source_sha256],['Supplied units',coi.supplied_units],['Matched units',coi.matched_units],['Defaulted units',coi.defaulted_units],['Ignored units',coi.ignored_units],['Adjusted edges',coi.applied_edges],['Changed edges',coi.changed_edges],['Formula',coi.formula]]});
// Execution completion is separate from the native candidate's measured constraints.
function stateConstraintCells(row){
 if(row.status!=='ok')return ['Not recorded','Not recorded','Not recorded'];
 const output=row.result?.prepared?.result??row.result?.configured_run?.result;
 const m=output?.metrics??output;
 const yesNo=value=>value===true?'Yes':value===false?'No':'Not recorded';
 const connected=typeof m?.contiguous==='boolean'?m.contiguous:
  Array.isArray(m?.connected)&&m.connected.length>0&&m.connected.every(v=>typeof v==='boolean')?m.connected.every(Boolean):undefined;
 return [yesNo(m?.within_requested_tolerance),Number.isFinite(m?.max_deviation_percent)?scalar(m.max_deviation_percent):'Not recorded',yesNo(connected)];
}
function recordedAuxiliaryTables(result){
 const metrics=result.replay?.result?.metrics??result.replay?.result?.evidence,partisan=metrics?.native_partisan_source_evidence,coi=metrics?.native_coi_source_evidence,tables=[];
 const pipeline=metrics?.native_weighting_evidence;
 if(pipeline){const w=pipeline.resolved_weights??{},stages=[w.geographic&&'Geographic base',w.minority_weighting&&'Minority override',w.partisan_shares&&'Partisan override',w.alpha_county>1e-10&&'County adjustment',w.economic_character&&'Economic character',w.housing_character&&'Housing character'].filter(Boolean);tables.push({title:'Native weighting pipeline',note:'Stages follow native order. Only the Compose route runs them; SingleDistrict and Unweighted keep the native skip rules. A later override may replace an earlier base. Sparse weight maps remain sparse.',headings:['Field','Value'],rows:[['Route',scalar(pipeline.route)],['Configured stage order',stages.join(' → ')||'No active composer stages'],['Sparse weighted edges',String(pipeline.effective_sparse_edges?.length??0)],['Zone behavior',w.zone_membership?'Native spatial-join fallback':'Not configured']]});}
 const demo=metrics?.native_demographic_source_evidence;
 if(demo)tables.push({title:'Recorded demographic data',note:demo.status==='native-reader-aligned'?'Native total-population CSV rules apply: numeric parse defaults are zero, duplicate rows use the last row, and missing graph units use fraction 0. Nonfinite observations remain identified; these are not VAP counts.':demo.status==='native-absent-method-fallback'?'The native method uses its recorded absent-file fallback. No demographic observations were fabricated.':'No demographic rows are consumed on this native weighting route.',headings:['Field','Value'],rows:[['Status',scalar(demo.status)],['Selected source',scalar(demo.source_name)],['Source SHA-256',scalar(demo.source_sha256)],['Recorded absence claim',demo.recorded_absence_claim?'Yes':'No'],['Matched units',scalar(demo.matched_units)],['Units using fraction 0',scalar(demo.defaulted_units)],['Ignored source units',scalar(demo.ignored_units)],['Nonfinite observations',Array.isArray(demo.nonfinite_unit_ids)?String(demo.nonfinite_unit_ids.length):'Not read']]});

 if(partisan)tables.push({title:'Recorded partisan data',note:partisan.status==='skipped-single-district-native-weighting'?'The native single-district route does not read partisan shares. The selected bytes or absence claim are retained.':'Native TSV rules apply: duplicate IDs use the last row, GEOIDs are padded to eleven characters, and graph units without shares use 0.5.',headings:['Field','Value'],rows:[['Status',scalar(partisan.status)],['Selected source',scalar(partisan.source_name)],['Source SHA-256',scalar(partisan.source_sha256)],['Matched units',scalar(partisan.matched_units)],['Units using default 0.5',scalar(partisan.defaulted_units)],['Ignored source units',scalar(partisan.ignored_units)]]});
 if(coi)tables.push({title:'Recorded COI data',note:coi.status==='native-warning-fallback'?'Warning: the native COI adjustment failed. Replay preserves the entire previously computed weight map, matching the native fallback.':coi.scope,headings:['Field','Value'],rows:[['Status',scalar(coi.status)],['Selected source',scalar(coi.source_name)],['Source SHA-256',scalar(coi.source_sha256)],['Recorded absence claim',coi.recorded_absence_claim?'Yes':'No'],['Previous weights preserved',coi.computed_weights_preserved?'Yes':'Not a fallback'],['Matched units',scalar(coi.matched_units)],['Changed edges',scalar(coi.changed_edges)],['Warning detail',scalar(coi.error)]]});
 const characters=metrics?.native_character_source_evidence?[metrics.native_character_source_evidence]:[metrics?.native_economic_source_evidence,metrics?.native_housing_source_evidence].filter(Boolean);
 for(const character of characters)tables.push({title:'Recorded character data · '+scalar(character.kind),note:character.status==='skipped-single-district-native-weighting'?'The native single-district route does not read character data. The selected bytes or absence claim are retained.':character.status==='skipped-native-weighting-route'?'The native unweighted route does not read character data. The selected bytes or absence claim are retained.':character.status==='native-warning-fallback'?'Warning: native character data is absent, empty or could not be read. Replay preserves the previously computed weights.':character.kind==='economic'?'Native exact-ID alignment applies. Unmatched graph units receive the native zero economic vector.':'Native exact-ID alignment applies. Unmatched graph units receive the native neutral housing vector.',headings:['Field','Value'],rows:[['Kind',scalar(character.kind)],['Status',scalar(character.status)],['Selected source',scalar(character.source_name)],['Source SHA-256',scalar(character.source_sha256)],['Recorded absence claim',character.recorded_absence_claim?'Yes':'No'],['Native reader status',scalar(character.native_status)],['Matched units',scalar(character.matched_units)],['Missing units',Array.isArray(character.missing_unit_ids)?String(character.missing_unit_ids.length):'Not aligned'],['Ignored source units',Array.isArray(character.ignored_source_ids)?String(character.ignored_source_ids.length):'Not aligned'],['Previous weights preserved',character.computed_weights_preserved?'Yes':'Not a fallback'],['Warning detail',scalar(character.error??character.reason)]]});
 return tables;
}
function exactRecipeSetting(binding,key,value){
 const encoded=binding?.native64_readonly?.[key];
 return typeof encoded==='string'?encoded:typeof value==='string'?value:value===undefined?'Not checked':JSON.stringify(value);
}
function readonlyRecipeTables(binding){
 const raw=binding?.native64_readonly?.unsigned_integers;
 if(!Array.isArray(raw))return [];
 const rows=raw.filter(v=>v&&typeof v.pointer==='string'&&typeof v.decimal==='string'&&/^(0|[1-9][0-9]*)$/.test(v.decimal)).slice(0,100);
 return [{title:'Recorded integer settings',note:'Exact decimal metadata. Inspection and Open do not run these settings; execution checks the selected method and its limits separately.',headings:['Recorded setting','Exact value'],rows:rows.map(v=>[v.pointer.replace('/state/algorithm/seeds/','Search / ').replace('/state/algorithm/split/','Structure / ').replace('/state/algorithm/metis/','METIS / ').replace('/state/','').replaceAll('_',' '),v.decimal])}];
}
function nativeAlgorithmGeometryTables(result){
 const g=result?.source_check?.sources?.algorithm_geometry??result?.sources?.algorithm_geometry;
 if(!g)return [];
 const ids=Array.isArray(g.unit_ids)?g.unit_ids:[],areas=Array.isArray(g.land_areas_m2)?g.land_areas_m2:[];
 return [{title:'Recorded algorithm land areas',note:'Native TIGER ALAND values and alignment. Circular perimeter estimates are algorithm inputs, not measured polygon perimeters.',headings:['Field','Value'],rows:[['Source outcome',scalar(g.status)],['TIGER records',scalar(g.observations)],['Duplicate tract records',scalar(g.duplicate_records)],['Graph units missing a TIGER record',scalar(g.missing_unit_ids?.length)],['Native path opened',g.path_opened?'Yes':'No'],['Detail',scalar(g.error??'No reader error')]]},...(areas.length?[{title:'Land area alignment',note:'First 100 units in graph order; complete values and original source bytes remain in the saved project.',headings:['Unit ID','Land area (m²)'],rows:ids.slice(0,100).map((id,i)=>[scalar(id),scalar(areas[i])])}]:[])];
}
function recordedExecutionTables(result,recorded){
 const execution=recorded?.execution,run=result.replay?.result;
 if(!execution)return [];
 const report=run?.build_report,attempts=report?.attempts??[],multiscale=execution.multiscale_sampler!=null;
 let prepared;try{prepared=JSON.parse(result.prepared?.prepared_request_json??'null');}catch{}
 const input=prepared?.input,yesNo=v=>typeof v==='boolean'?(v?'Yes':'No'):'Not evaluated';
 const seed=v=>v===null?'Omitted in original run':v===undefined?'Not evaluated':scalar(v);
 return [{title:multiscale?'Recorded multiscale execution':'Recorded execution details',
  note:multiscale?'Requested seed starts the run; accepted seed identifies the first population-passing attempt. Weights apply to the tract seed; fine/coarse sampling and ranking use unweighted edges. Reported plan measures use the returned fine units.':'Requested seed and accepted seed are distinct when native population retries occur.',
  headings:['Field','Value'],rows:[
   ['Original requested seed',seed(recorded?.state?.algorithm?.metis?.seed)],
   ['Recorded accepted seed',seed(execution.accepted_seed)],
   ['Recorded retry attempt (zero-based)',scalar(execution.balance_retry_attempt)],
   ['Replayed requested seed',seed(attempts[0]?.seed)],
   ['Replayed accepted seed',seed(attempts.at(-1)?.seed)],
   ['Execution evidence equal',yesNo(result.execution_comparison?.equal)],
   ...(multiscale?[
    ['Sampler profile',scalar(execution.multiscale_sampler)],
    ['Parent tract units',scalar(input?.request?.graph?.geoids?.length)],
    ['Returned fine scale',scalar(input?.fine_level)],
    ['Returned fine units',scalar(run?.assignments?Object.keys(run.assignments).length:input?.block_groups?.geoids?.length??input?.request?.graph?.geoids?.length)],
    ['Coarse scale',scalar(input?.coarse_level)],
    ['Population within requested tolerance',yesNo(run?.within_requested_tolerance)],
    ['All districts connected',yesNo(Array.isArray(run?.connected)?run.connected.every(v=>v===true):undefined)]
   ]:[])
  ]}];
}

