 if(result?.schema_version==='bisect-state-run-years-v1')return [{title:'Multi-year state Run',note:result.scope+' Execution counts do not establish population balance or contiguity. Inspect each year’s state results for native candidate checks.',headings:['Field','Value'],rows:[['Status',scalar(result.status)],['Native year order','2020, 2010, 2000'],['Exit status',scalar(result.exit_code)],['Completed years',scalar(result.summary?.completed)],['Executed state runs',scalar(result.state_summary?.succeeded)],['Execution failures',scalar(result.state_summary?.failed)],['WASM SHA-256',scalar(result.runtime_artifact?.sha256)]]},{title:'Per-year outcomes',headings:['Year','Status','Queued states','Executed','Execution failures','Error'],rows:(Array.isArray(result.years)?result.years:[]).slice(0,3).map(row=>[scalar(row.year),scalar(row.status),scalar(row.result?.summary?.total),scalar(row.result?.summary?.succeeded),scalar(row.result?.summary?.failed),scalar(row.error)])},...(result.years||[]).slice(0,3).flatMap(row=>row.result?.schema_version==='bisect-state-run-batch-v1'?countResultTables(row.result).filter(table=>table.title==='State results'||table.title.startsWith('Partition timing')).map(table=>({...table,title:String(row.year)+' state results'})):[])];

