 if(result?.schema_version==='bisect-round-map-directory-v1')return [{title:'Native round folder maps',note:result.scope,headings:['Round','Folder','Output','Status','Assigned units','Units filled as zero','Failure stage','Error'],rows:result.rows.map(row=>[row.index,row.directory,row.output_path,row.status,row.map?.round_assigned_units??'',row.map?.round_unassigned_units??'',row.failure_stage||'',row.error||''])}];
